 #[test]fn audio_windows_root_startup_matches18_native_failure_banks_for_slot_calloc_publication_and_retains_unpublished_allocation(){let p=fixture();let mut count=0;for row in p["cases"].as_array().unwrap().iter().filter(|v|v["layout"]=="all"&&v["failure"]!="none"){let c=prepare(&p,row);let heap_report=c.services.inner.heap.report();let locks_report=c.services.locks.report();let null_calloc=row["failure"]=="calloc";let failure_kind=row["failure"].as_str().unwrap().to_owned();let context=Context{memory:c.memory,dead:c.dead,services:Fault{inner:c.services,null_calloc}};let started=initialize_with(context,None,|_|if failure_kind=="slot"{Err(Failure::Windows{operation:"FlsAlloc",code:8})}else{SharedSlot::new()},|_,_,_|Ok(false)).unwrap();assert_eq!(started.status,0);assert!(started.slot.is_none());assert!(started.current().is_err());started.context.with(|c|{let view=Context{memory:BTreeMap::new(),dead:BTreeSet::new(),services:NativeGlobal::new(0x73000000).unwrap()};let _view=view;assert_eq!(get(&c.memory,&c.dead,0x12230cc,4).unwrap(),u32::MAX);assert!(c.services.inner.locks.is_empty());let native=&c.services.inner;let cookie=row["cookie"].as_u64().unwrap()as u32;let _cookie=cookie;if failure_kind=="set"{let r=started.initial_record.unwrap();assert_eq!(r,0x50000000);assert_eq!(c.memory[&r].raw,vec![0;956]);assert_eq!(native.inner.heap.outstanding(),1);assert_eq!((heap_report.allocations(),heap_report.frees()),(1,0));}else{assert!(started.initial_record.is_none());assert_eq!(native.inner.heap.outstanding(),0);assert_eq!(heap_report.allocations(),0);}assert!(c.dead.is_empty());}).unwrap();drop(started);assert_eq!(heap_report.allocations(),heap_report.frees());assert!(heap_report.failures().is_empty()&&locks_report.failures().is_empty());count+=1;}assert_eq!(count,18);}
 #[test]fn audio_windows_root_startup_rejects_existing_foreign_slot_before_any_global_or_lock_initialization(){let p=fixture();let row=p["cases"].as_array().unwrap().iter().find(|v|v["layout"]=="all"&&v["failure"]=="none").unwrap();let mut c=prepare(&p,row);put(&mut c.memory,&c.dead,0x12230cc,4,7).unwrap();let report=c.services.inner.heap.report();assert!(matches!(initialize(c,Some(retire)),Err(Failure::InvalidContext(_))));assert_eq!((report.allocations(),report.frees()),(0,0));assert!(report.failures().is_empty());}
